# typed: false
# frozen_string_literal: true

# Late enforcement. Generated by tools/generate_overlays.py from
# tools/late_results/actions.json; do not edit.
#
# account.risk_changed only wakes the handler. LateResults.handle_risk_change
# verifies the delivery, reads the account's current risk
# (GET /v1/accounts/{account_id}), asks your get_account_state where the
# account is in your own flow, and takes the actions the table names for that
# state and the decision of its flow:
#
#   onboarding   account_creation allow         activate
#   onboarding   account_creation review/block  fail_onboarding, revoke_sessions
#   provisional  account_creation allow         activate
#   provisional  account_creation review/block  reject_activation, revoke_sessions
#   active       login review                   revoke_sessions
#   active       login block                    restrict, revoke_sessions
#   restricted   login allow                    unrestrict, when flows['login'].reinstate
#
# Every action, or none, is recorded with accounts.record_enforcement at the
# risk_version read, and a refused action is recorded as failed and raised. No
# action deletes a user. The same table and vectors
# (tests/fixtures/late-results-vectors.json) run in every SDK.

require 'erb'
require 'faraday'
require 'json'

module NoResponse
  module LateResults
    TABLE = JSON.parse('{"lifecycle":{"onboarding":{"flow":"account_creation","on":{"allow":["activate"],"review":["fail_onboarding","revoke_sessions"],"block":["fail_onboarding","revoke_sessions"]}},"provisional":{"flow":"account_creation","on":{"allow":["activate"],"review":["reject_activation","revoke_sessions"],"block":["reject_activation","revoke_sessions"]}},"active":{"flow":"login","on":{"review":["revoke_sessions"],"block":["restrict","revoke_sessions"]}},"restricted":{"flow":"login","on":{},"reinstate":{"allow":["unrestrict"]}},"rejected":{"flow":"account_creation","on":{}}},"providers":{"clerk":{"base_url":"https://api.clerk.com/v1","actions":{"fail_onboarding":[{"call":{"method":"POST","path":"/users/{user}/ban"}}],"reject_activation":[{"call":{"method":"POST","path":"/users/{user}/ban"}}],"activate":[],"restrict":[{"call":{"method":"POST","path":"/users/{user}/ban"}}],"unrestrict":[{"call":{"method":"POST","path":"/users/{user}/unban"}}],"revoke_sessions":[{"each":{"list":{"method":"GET","path":"/sessions","query":{"user_id":"{user}","status":"active","limit":"100"}},"page":{"kind":"offset","param":"offset","size":100},"where":{"status":"active"}},"call":{"method":"POST","path":"/sessions/{item}/revoke"}}]}},"workos":{"base_url":"https://api.workos.com","actions":{"fail_onboarding":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":"onboarding_failed"}}}}],"reject_activation":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":"activation_rejected"}}}}],"activate":[],"restrict":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":"restricted"}}}}],"unrestrict":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":null}}}}],"revoke_sessions":[{"each":{"list":{"method":"GET","path":"/user_management/users/{user}/sessions","query":{"limit":"100"}},"page":{"kind":"cursor","param":"after","next":["list_metadata","after"]},"where":{"status":"active"}},"call":{"method":"POST","path":"/user_management/sessions/revoke","body":{"session_id":"{item}"}}}]}},"auth0":{"base_url":"https://{domain}/api/v2","actions":{"fail_onboarding":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}],"reject_activation":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}],"activate":[],"restrict":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}],"unrestrict":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":false}}}],"revoke_sessions":[{"call":{"method":"DELETE","path":"/users/{user}/sessions"},"fallback":{"status":403,"code":"feature_not_enabled","reports":"restrict","steps":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}]}},{"call":{"method":"DELETE","path":"/users/{user}/refresh-tokens"},"fallback":{"status":403,"code":"feature_not_enabled","steps":[{"each":{"list":{"method":"GET","path":"/device-credentials","query":{"user_id":"{user}","type":"refresh_token","per_page":"100"}},"page":{"kind":"index","param":"page","size":100}},"call":{"method":"DELETE","path":"/device-credentials/{item}"}},{"each":{"list":{"method":"GET","path":"/device-credentials","query":{"user_id":"{user}","type":"rotating_refresh_token","per_page":"100"}},"page":{"kind":"index","param":"page","size":100}},"call":{"method":"DELETE","path":"/device-credentials/{item}"}}]}}]}}},"limits":{"retries":4,"budget_ms":3000,"backoff_ms":250,"max_pages":100}}').freeze
    LIMITS = TABLE.fetch('limits')
    # Every action a provider runs, as the table names them.
    ACTIONS = TABLE.fetch('providers').values.first.fetch('actions').keys.freeze

    # Where the account is in your flow, from get_account_state. user_id is the
    # provider's user id (default: the account id). enforced_risk_version is
    # the risk_version you last enforced (a result's risk_version that you
    # stored); an account at or below it is skipped.
    AccountStateAnswer = Struct.new(:state, :user_id, :enforced_risk_version, keyword_init: true)

    # reinstate lifts a restriction once the flow's decision is allow again. Off by default.
    FlowPolicy = Struct.new(:reinstate, keyword_init: true)

    Enforced = Struct.new(:flow, :action, :status, :error_code, keyword_init: true)

    # event is the verified event (from handle_risk_change). risk_version is the
    # version acted on: store it and return it as enforced_risk_version. skipped
    # says why nothing was done: not_actionable (not account.risk_changed, or a
    # test event), account_gone (erased), unknown_user (get_account_state
    # returned nil) or already_enforced. enforcements is what was recorded, in order.
    EnforcementResult = Struct.new(:event, :account, :state, :risk_version, :skipped, :enforcements, keyword_init: true)

    # The provider refused an action or could not be reached (status 0). Answer
    # the webhook with a 5xx so it is delivered again. code is the provider's
    # error code, such as Auth0's errorCode "insufficient_scope", when it sent one.
    class ProviderActionError < StandardError
      attr_reader :provider, :status, :code

      def initialize(provider, status, message, code = nil)
        super(message)
        @provider = provider
        @status = status
        @code = code
      end
    end

    SLUG = /\A[a-z0-9_.-]+\z/

    class << self
      # Verify an account.risk_changed delivery and enforce the account's
      # current risk. A delivery that fails verification raises
      # WebhookVerification::VerificationError before anything is read; any
      # other event, and a test event, does nothing.
      #
      # with_account_lock serializes enforcement of one account across your
      # workers. It is called with the account id and a callable: hold an
      # exclusive lock on the account, call the callable, store the result's
      # risk_version and any state change, then release the lock. An exception
      # must propagate. Inside the lock the handler reads the account's risk and
      # your state again, so a stale event or listed account cannot undo a newer
      # decision. Without it, overlapping calls can act on an old decision after
      # a newer one.
      def handle_risk_change(client, payload, headers, secrets, provider:, get_account_state:, flows: {},
                             tolerance_seconds: WebhookVerification::DEFAULT_TOLERANCE_SECONDS, now: nil,
                             with_account_lock: nil)
        event = WebhookVerification.construct_event(payload, headers, secrets, tolerance_seconds: tolerance_seconds, now: now)
        if event.type != 'account.risk_changed' || (event.respond_to?(:test) && event.test == true)
          return EnforcementResult.new(event: event, skipped: 'not_actionable', enforcements: [])
        end

        result = under_account_lock(client, event.data.account.id, provider, get_account_state, flows, with_account_lock)
        result.event = event
        result
      end

      # Enforce one account: the account a handler fetched, or one from
      # accounts.list_changed(unenforced: true) when catching up. With
      # with_account_lock the account is read again inside the lock; without it
      # the account is enforced as given.
      def enforce_account(client, account, provider:, get_account_state:, flows: {}, with_account_lock: nil)
        return under_account_lock(client, account.id, provider, get_account_state, flows, with_account_lock) if with_account_lock

        enforce_as_read(client, account, provider, get_account_state, flows)
      end

      # Clerk, WorkOS or Auth0, run from the shared action table. token is the
      # Clerk secret key, WorkOS API key or Auth0 Management API token; domain
      # is the Auth0 tenant domain. Pass http (a Faraday connection) for a proxy or for tests.
      def identity_provider(name, token:, domain: nil, base_url: nil, http: nil)
        name = name.to_s
        spec = TABLE.fetch('providers')[name] or raise ArgumentError, "unknown identity provider #{name.inspect}"
        raise ArgumentError, "#{name} needs token" if token.to_s.empty?

        base = base_url || spec.fetch('base_url')
        if base.include?('{domain}')
          raise ArgumentError, "#{name} needs domain or base_url" if domain.to_s.empty?

          base = base.sub('{domain}', domain)
        end
        TableProvider.new(name, spec, base.sub(%r{/+\z}, ''), token, http || Faraday.new(request: { timeout: 10 }))
      end

      # Your own user store: one callable per action you support, keyed by
      # action. A callable may return other actions it ran. An action without one fails.
      def custom_provider(handlers)
        CustomProvider.new(handlers.transform_keys(&:to_s))
      end

      private

      # Read the account's current risk and enforce it, inside with_account_lock when you gave one.
      def under_account_lock(client, account_id, provider, get_account_state, flows, with_account_lock)
        enforce = lambda do
          begin
            account = client.accounts.get(account_id: account_id).result
          rescue Models::Errors::NotFoundError
            next EnforcementResult.new(skipped: 'account_gone', enforcements: [])
          end
          enforce_as_read(client, account, provider, get_account_state, flows)
        end
        return enforce.call unless with_account_lock

        result = nil
        with_account_lock.call(account_id, -> { result = enforce.call })
        result or raise 'with_account_lock returned without running enforce'
      end

      def enforce_as_read(client, account, provider, get_account_state, flows)
        answer = get_account_state.call(account)
        return EnforcementResult.new(account: account, skipped: 'unknown_user', enforcements: []) if answer.nil?

        state = answer.state.to_s
        rule = TABLE.fetch('lifecycle')[state] or raise ArgumentError, "unknown account state #{state.inspect}"
        risk_version = account.risk_version
        if !answer.enforced_risk_version.nil? && risk_version <= answer.enforced_risk_version
          return EnforcementResult.new(account: account, state: state, risk_version: risk_version,
                                       skipped: 'already_enforced', enforcements: [])
        end

        flow = rule.fetch('flow')
        decision = account.decisions_by_flow.public_send(flow).to_s
        policy = (flows || {})[flow] || (flows || {})[flow.to_sym]
        actions = rule.fetch('on')[decision]
        actions = (rule['reinstate'] || {})[decision] if actions.nil? && policy&.reinstate
        enforcements = []
        record = lambda do |action, status, error_code = nil|
          body = Models::Shared::EnforcementRequest.new(
            risk_version: risk_version,
            flow: Models::Shared::Flow.deserialize(flow),
            action: Models::Shared::EnforcementAction.deserialize(action),
            state_before: Models::Shared::EnforcementState.deserialize(state),
            status: Models::Shared::EnforcementStatus.deserialize(status),
            provider: Models::Shared::EnforcementProvider.deserialize(provider.name),
            error_code: error_code
          )
          client.accounts.record_enforcement(account_id: account.id, body: body)
          enforcements << Enforced.new(flow: flow, action: action, status: status, error_code: error_code)
        end

        if actions.nil? || actions.empty?
          # A decision that needs nothing, allow too, still counts as handled, so the account leaves the unenforced feed.
          record.call('none', 'applied')
          return EnforcementResult.new(account: account, state: state, risk_version: risk_version, enforcements: enforcements)
        end

        recorded = {}
        user_id = answer.user_id.to_s.empty? ? account.id : answer.user_id
        actions.each do |action|
          begin
            also_ran = provider.run(action, user_id)
          rescue StandardError => e
            record.call(action, 'failed', failure_code(provider.name, e))
            raise
          end
          [*also_ran, action].each do |ran|
            next if recorded[ran]

            recorded[ran] = true
            record.call(ran, 'applied')
          end
        end
        EnforcementResult.new(account: account, state: state, risk_version: risk_version, enforcements: enforcements)
      end

      # The error_code of a failed action: the provider's code, else its HTTP status, as <provider>.<code>.
      def failure_code(provider, error)
        code = error.respond_to?(:code) ? error.code : nil
        status = error.is_a?(ProviderActionError) ? error.status : nil
        suffix =
          if code.is_a?(String) && code.downcase.match?(SLUG) then code.downcase
          elsif status&.zero? then 'unreachable'
          elsif status then "http_#{status}"
          else
            'error'
          end
        "#{provider}.#{suffix}"[0, 128]
      end
    end

    # Runs one action of the shared table against a provider's admin API.
    class TableProvider
      attr_reader :name

      def initialize(name, spec, base, token, http)
        @name = name
        @spec = spec
        @base = base
        @authorization = "Bearer #{token}"
        @http = http
      end

      # Take the action and return any other action that had to run with it (Auth0 restricts to end a session).
      def run(action, user_id)
        raise ArgumentError, 'user id must be a non-empty string' unless user_id.is_a?(String) && !user_id.empty?

        steps = @spec.fetch('actions')[action.to_s] or raise ArgumentError, "unknown action #{action.inspect}"
        # Per call, so one provider can serve concurrent deliveries.
        run_steps(steps, Call.new(user_id, 0.0))
      end

      private

      # The user acted on and the time spent waiting out 429s in this action.
      Call = Struct.new(:user, :waited_ms)

      def run_steps(steps, call)
        also_ran = []
        steps.each do |step|
          if step['each']
            collect(step['each'], call).each { |item| send_call(step['call'], call, item) }
            next
          end
          begin
            send_call(step['call'], call)
          rescue ProviderActionError => e
            fallback = step['fallback']
            raise unless fallback && e.status == fallback['status'] && e.code == fallback['code']

            also_ran.concat(run_steps(fallback['steps'], call))
            also_ran << fallback['reports'] if fallback['reports']
          end
        end
        also_ran
      end

      # Every matching item id across the list's pages, collected before any is acted on.
      def collect(each, call)
        listing = each['list']
        page = each['page']
        where = each['where'] || {}
        ids = []
        cursor = nil
        LIMITS['max_pages'].times do |index|
          query = (listing['query'] || {}).dup
          case page['kind']
          when 'offset' then query[page['param']] = (index * page['size']).to_s
          when 'index' then query[page['param']] = index.to_s
          else query[page['param']] = cursor unless cursor.nil?
          end
          body = send_call(listing.merge('query' => query), call)
          items =
            if body.is_a?(Array) then body
            elsif body.is_a?(Hash) && body['data'].is_a?(Array) then body['data']
            else
              []
            end
          items.each do |item|
            next unless item.is_a?(Hash) && item['id'].is_a?(String) && !item['id'].empty?

            ids << item['id'] if where.all? { |key, value| item[key] == value }
          end
          if page['kind'] == 'cursor'
            following = page['next'].reduce(body) { |node, key| node.is_a?(Hash) ? node[key] : nil }
            break unless following.is_a?(String) && !following.empty?

            cursor = following
          elsif items.length < page['size']
            break
          end
        end
        ids
      end

      def fill(value, user, item)
        case value
        when String then value.gsub('{user}', user).gsub('{item}', item.to_s)
        when Array then value.map { |entry| fill(entry, user, item) }
        when Hash then value.transform_values { |entry| fill(entry, user, item) }
        else value
        end
      end

      def number(text)
        value = Float(text.to_s.strip, exception: false)
        value&.finite? ? value : nil
      end

      # How long a 429 asks to wait, in milliseconds.
      def rate_limit_wait_ms(headers, retry_count)
        after = number(headers['retry-after'])
        return after * 1000 if after && after >= 0

        reset = number(headers['x-ratelimit-reset'])
        return [0.0, (reset * 1000) - (Time.now.to_f * 1000)].max if reset

        (LIMITS['backoff_ms'] * (2**retry_count)).to_f
      end

      # The provider's error code: Auth0's errorCode, WorkOS's code or Clerk's errors[0].code.
      def error_code(text)
        body = JSON.parse(text.to_s)
        return nil unless body.is_a?(Hash)

        code = body['errorCode'] || body['code']
        errors = body['errors']
        code = errors.first['code'] if code.nil? && errors.is_a?(Array) && errors.first.is_a?(Hash)
        code.is_a?(String) && !code.empty? ? code : nil
      rescue JSON::ParserError
        nil
      end

      # One admin API call. A 404 is done (nil); a 429 is waited out inside the action's budget; any other failure raises.
      def send_call(request, call, item = nil)
        path = request['path'].gsub('{user}', ERB::Util.url_encode(call.user)).gsub('{item}', ERB::Util.url_encode(item.to_s))
        query = (request['query'] || {}).transform_values { |value| fill(value, call.user, item) }
        url = @base + path
        url += "?#{URI.encode_www_form(query)}" unless query.empty?
        headers = { 'Authorization' => @authorization, 'Accept' => 'application/json' }
        body = nil
        if request.key?('body')
          body = JSON.generate(fill(request['body'], call.user, item))
          headers['Content-Type'] = 'application/json'
        end
        label = "#{@name} #{request['method']} #{request['path']}"
        retry_count = 0
        loop do
          begin
            response = @http.run_request(request['method'].downcase.to_sym, url, body, headers)
          rescue Faraday::Error => e
            raise ProviderActionError.new(@name, 0, "#{label} failed: #{e.message}")
          end
          if response.status == 429 && retry_count < LIMITS['retries']
            wait = rate_limit_wait_ms(response.headers, retry_count)
            if call.waited_ms + wait <= LIMITS['budget_ms']
              call.waited_ms += wait
              sleep(wait / 1000.0)
              retry_count += 1
              next
            end
          end
          return nil if response.status == 404
          unless (200..299).cover?(response.status)
            raise ProviderActionError.new(@name, response.status, "#{label} answered #{response.status}", error_code(response.body))
          end
          return nil if response.body.to_s.empty?

          begin
            return JSON.parse(response.body)
          rescue JSON::ParserError
            return nil
          end
        end
      end
    end

    # Your own user store, from custom_provider.
    class CustomProvider
      def initialize(handlers)
        @handlers = handlers
      end

      def name = 'custom'

      def run(action, user_id)
        handler = @handlers[action.to_s] or raise ArgumentError, "custom_provider has no #{action} handler"
        also_ran = handler.call(user_id)
        # Only an array of action names counts; any other return value (nil, true, a model) is no extra action.
        return [] unless also_ran.is_a?(Array)

        also_ran.map(&:to_s).select { |name| ACTIONS.include?(name) }
      end
    end
  end
end
